import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,q as a,P as n}from"./D3cAVrQp.js";const r={title:"The Sovereign Debt Transformation Protocol: From Extraction to Regeneration",author:"Björn Kenneth Holmström",date:"2026-03-13",description:"A framework for converting sovereign debt obligations from claims on extraction into stakes in verified regeneration, using the Hearts and Leaves currency architecture of the Global Governance Frameworks. Addressed to economists, legal scholars, policymakers, Indigenous governance practitioners, and civil society organizations as an open research hypothesis.",status:"draft",category:"economics",version:"0.1",pages:36,readTime:40,pdfPath:"/resources/whitepapers/Sovereign_Debt_Transformation_Protocol.pdf",tags:["Sovereign Debt","Regenerative Economics","Global Governance","Climate Finance","Hearts and Leaves","Ecological Restoration","Care Economy","Development Finance"],hashtags:["SovereignDebtTransformation","RegenerativeEconomics","DebtJustice","BridgetownInitiative","GlobalGovernanceFrameworks"]},{title:d,author:h,date:u,description:p,status:m,category:g,version:f,pages:b,readTime:v,pdfPath:y,tags:w,hashtags:T}=r;var o=i('<hr> <p><strong>Version:</strong> 0.1 (Working draft — not for citation) <strong>Date:</strong> March 2026 <strong>Authors:</strong> Global Governance Frameworks Research Collective <strong>Contact:</strong> globalgovernanceframeworks.org <strong>Estimated final length:</strong> 80–100 pages <strong>Status:</strong> Open for expert consultation and co-development</p> <p><em>This document is a research hypothesis, not a finished blueprint. We invite economists, legal scholars, policymakers, Indigenous governance practitioners, and civil society organizations to engage critically with the ideas presented here.</em></p> <hr> <h2><a id="abstract"></a>Abstract</h2> <p>The global sovereign debt system is structurally broken — not because of bad actors or policy failures, but because its underlying architecture produces extraction as a required output. Nations borrow in foreign currencies, service those debts by converting natural wealth into tradable commodities, and remain trapped in a growth imperative that accelerates ecological collapse while rarely achieving debt reduction.</p> <p>This paper introduces the <strong>Sovereign Debt Transformation Protocol (SDTP)</strong>: a mechanism for converting sovereign debt obligations from claims on extraction into stakes in regeneration. Under the SDTP, debtor nations service obligations through verified ecological restoration and care infrastructure development, using an open measurement system anchored in the Hearts and Leaves currency architecture of the Global Governance Frameworks. Creditors receive instruments backed by real regenerative value rather than continued extraction. The protocol is governed by the Social Resilience Council under constitutional authority established in the Treaty for Our Only Home.</p> <p>The paper proceeds in six parts: a structural diagnosis of the debt-growth trap; a technical description of the transformation mechanism; macroeconomic viability analysis; a phased implementation pathway; guidance for specific stakeholder groups; and a research agenda for ongoing development. Throughout, we treat this as a rigorous hypothesis open to revision — the goal is to advance the conversation, not foreclose it.</p> <hr> <h2><a id="table-of-contents"></a>Table of contents</h2> <p><strong>In this paper:</strong></p> <ul><li><a href="#abstract">Abstract</a></li> <li><a href="#acknowledgments">Acknowledgments</a></li> <li><a href="#executive-summary">Executive summary</a></li> <li><strong><a href="#part-i">Part I: Diagnosis — The debt-growth trap</a></strong> <ul><li><a href="#chapter-1">Chapter 1: The architecture of extraction</a></li> <li><a href="#chapter-2">Chapter 2: Why growth cannot solve the problem it created</a></li> <li><a href="#chapter-3">Chapter 3: The limits of existing debt relief mechanisms</a></li></ul></li> <li><strong><a href="#part-ii">Part II: Design — The transformation mechanism</a></strong> <ul><li><a href="#chapter-4">Chapter 4: Core architecture and principles</a></li> <li><a href="#chapter-5">Chapter 5: Hearts and Leaves as debt-servicing instruments</a></li> <li><a href="#chapter-6">Chapter 6: Governance, verification, and the Social Resilience Council</a></li> <li><a href="#chapter-7">Chapter 7: Legal framework and creditor integration</a></li></ul></li> <li><strong><a href="#part-iii">Part III: Viability</a></strong> <ul><li><a href="#chapter-8">Chapter 8: Macroeconomic stability analysis</a></li> <li><a href="#chapter-9">Chapter 9: Risk management and failure modes</a></li> <li><a href="#chapter-10">Chapter 10: Comparison with alternatives</a></li></ul></li> <li><strong><a href="#part-iv">Part IV: Implementation</a></strong> <ul><li><a href="#chapter-11">Chapter 11: Three-phase transition pathway</a></li> <li><a href="#chapter-12">Chapter 12: Pilot program designs</a></li> <li><a href="#chapter-13">Chapter 13: Capacity building requirements</a></li></ul></li> <li><strong><a href="#part-v">Part V: Pathways to partnership</a></strong> <ul><li><a href="#chapter-14">Chapter 14: Guidance for specific stakeholder groups</a></li></ul></li> <li><strong><a href="#part-vi">Part VI: Conclusion and research agenda</a></strong> <ul><li><a href="#chapter-15">Chapter 15: What this paper has and has not established</a></li> <li><a href="#chapter-16">Chapter 16: Research agenda</a></li></ul></li> <li><a href="#appendices">Appendix outline</a></li></ul> <hr> <h2><a id="acknowledgments"></a>Acknowledgments</h2> <p><em>This section will credit contributing researchers, expert reviewers, Indigenous knowledge keepers consulted during development, and funding sources. To be completed prior to formal release.</em></p> <hr> <h2><a id="executive-summary"></a>Executive summary</h2> <h3>The crisis in numbers</h3> <p>Approximately $11 trillion in sovereign debt is held by Global South nations. Many of these countries spend more on annual debt service than on healthcare, education, and climate adaptation combined. In the most heavily indebted cases, this is not a temporary cash flow problem — it is a permanent structural condition. The debt does not decrease; it compounds.</p> <p>The 2010–2018 Greek crisis illustrates the dynamic at a smaller scale. A €300 billion debt, subject to Troika restructuring conditions, had grown to over €350 billion by the end of the “rescue.” GDP contracted by 25 percent. Unemployment reached 28 percent. The mechanism designed to resolve the crisis instead transferred wealth from working people to creditors while destroying the social infrastructure needed for recovery. Greece is a middle-income European economy with significant institutional capacity. The outcomes for lower-income nations with weaker bargaining positions are systematically worse.</p> <p>The structural explanation is not complex. Sovereign debt denominated in foreign currency requires generating that currency to service it. Generating foreign currency at scale means exporting commodities — which means extracting them. The faster the debt compounds, the faster the extraction must proceed. The ecological damage from that extraction is not counted as a liability on any balance sheet. It is an externality absorbed by the future.</p> <p>This is not a bug in the system. It is the system operating as designed.</p> <h3>Why current approaches fail</h3> <p>Existing debt relief mechanisms — HIPC, DSSI, the G20 Common Framework, debt-for-nature swaps — share a common limitation: they address the quantity of debt without addressing its architecture. They reduce the amount owed while leaving in place the growth imperative that generates new debt. They are patches applied to structural failure.</p> <p>Debt-for-nature swaps come closest to the logic of the SDTP. Under these arrangements, a portion of debt is cancelled in exchange for commitments to conservation spending. But they have operated at small scale, suffered from verification problems, and have not challenged the underlying premise that debt obligations must ultimately be serviced through economic growth measured in GDP terms.</p> <p>The SDTP is not a larger or better-verified debt-for-nature swap. It is a different kind of instrument: a rearchitecting of what debt service means, grounded in a broader framework of regenerative economics.</p> <h3>The transformation mechanism</h3> <p>The core proposal is straightforward to state, though complex in implementation.</p> <p>Sovereign debt obligations are currently structured as claims on a nation’s future economic output, denominated in foreign currency. Under the SDTP, a portion of those obligations would be restructured as claims on verified regenerative output — specifically, verified ecological restoration (generating Leaves) and verified care infrastructure development (generating Hearts).</p> <p>Hearts and Leaves are the dual-currency instruments of the Global Governance Frameworks’ economic architecture. Leaves are ecological restoration credits, each backed by independently verified ecosystem services: carbon sequestration, biodiversity recovery, watershed health, and related metrics. Hearts are care economy credits, generated through verified development of community care infrastructure — healthcare access, early childhood provision, elder care, and related services that reduce structural vulnerability. Neither currency is speculative. Both are anchored in measurable real-world outcomes.</p> <p>Under the SDTP, debtor nations service debt by demonstrating verified regenerative output rather than generating foreign currency through extraction. Creditors receive instruments representing real ecological and social value, backed by the same measurement infrastructure used across the GGF’s regenerative economy. The transaction structure is:</p> <blockquote><p><em>Old obligation: “You owe us $X billion in hard currency, generate exports to pay it.”</em> <em>Transformed obligation: “You owe us verified regeneration equivalent to $X billion, here is how we measure and govern it.”</em></p></blockquote> <p>This is not debt forgiveness. Creditors do not absorb a loss. They exchange a claim on extraction for a stake in regeneration — one that, over time, produces more durable value precisely because it does not destroy the ecological base that underpins all economic activity.</p> <h3>Governance architecture</h3> <p>The SDTP operates within the constitutional framework established by the Treaty for Our Only Home. Treaty Pillar 4 (Debt Justice) and Pillar 3 (Crisis Response) provide the legal authority for debt transformation instruments. The Social Resilience Council (SRC), a key council within the Meta-Governance structure, manages conversion rates between regenerative outputs and debt obligations, oversees the verification infrastructure, and adjudicates disputes.</p> <p>Verification relies on the Love Ledger platform — the transparent, community-led infrastructure used to record care contributions and ecological restoration work across the GGF’s broader economic system. This is not a new bureaucracy. The SDTP attaches debt-servicing functionality to measurement infrastructure that exists for other reasons, reducing both cost and the risk of purpose-built systems being captured or gamed.</p> <p>Indigenous governance bodies hold substantive roles in both the SRC and the verification processes for ecological restoration. This is not symbolic. Indigenous communities often possess the most accurate long-term knowledge of ecological baselines and trajectories in their territories. Their participation is a quality assurance mechanism, not an add-on.</p> <h3>What makes this viable</h3> <p>The SDTP is not viable in the current global institutional landscape. It requires the Treaty framework to be in place, the SRC to be operational, and at least a coalition of creditor nations willing to participate. These are significant prerequisites.</p> <p>What makes this worth developing now is that the window for such structural change is not permanently closed — it opens during crises. The current moment, in which resource weaponization and debt distress are simultaneously visible in the same geopolitical events, is exactly the kind of moment when alternative architectures become legible to policy audiences. The Sovereign Debt Transformation Protocol should be technically developed and institutionally ready before that window opens, not after.</p> <p>The macroeconomic case — developed in Part III — shows that the SDTP does not require creditors to absorb losses, does not require debtor nations to subordinate development to conservation, and does not produce the currency volatility or capital flight risks that debt default scenarios generate. The comparison with alternatives (Chapter 10) shows it performs better than existing mechanisms on stability, ecological outcomes, and long-term debt reduction.</p> <h3>Implementation pathway</h3> <p>The SDTP is proposed in three phases:</p> <p><strong>Phase 1 (Years 1–3): Verification infrastructure and pilot programs.</strong> Establish the Love Ledger verification systems for Leaves and Hearts at pilot-program scale. Launch three to five country pilots in nations with existing strong civil society and ecological monitoring capacity. Develop the legal templates for debt transformation instruments with participating creditors.</p> <p><strong>Phase 2 (Years 4–7): Coalition building and framework expansion.</strong> Expand to 20–30 countries. Establish SRC governance as a functioning body. Develop secondary markets for Leaves instruments among impact investors and institutional creditors. Integrate with existing carbon market infrastructure.</p> <p><strong>Phase 3 (Years 8–15): Systemic integration.</strong> Full integration with multilateral lending frameworks. SRC conversion rates become a standard reference for sovereign debt restructuring negotiations. SDTP instruments are recognized in major creditor-nation legal systems.</p> <p>This is a fifteen-year horizon. It is not a response to the current crisis — it is the alternative architecture that needs to be ready when the exhaustion of current approaches creates political space for structural change.</p> <h3>An open invitation</h3> <p>This paper is a research hypothesis. The mechanism described here requires economic modeling that we have not yet completed, legal analysis we have not yet commissioned, and engagement with affected communities that has not yet begun. We release this working draft to invite that engagement — from economists willing to stress-test the macroeconomic claims, from legal scholars familiar with sovereign debt restructuring, from Indigenous governance practitioners whose participation is essential to the verification architecture, and from the creditor and debtor nation officials who would ultimately implement or reject this approach.</p> <p>The goal is not to win the argument. The goal is to ensure that when the argument becomes necessary, there is something worth arguing for.</p> <hr> <h2><a id="part-i"></a>Part I: Diagnosis — The debt-growth trap</h2> <hr> <h2><a id="chapter-1"></a>Chapter 1: The architecture of extraction</h2> <h3><a id="ch1-1"></a>1.1 How sovereign debt became a structural condition</h3> <p>Sovereign debt — governments borrowing to finance expenditure — is as old as the modern state. What changed in the mid-twentieth century was not the existence of debt but its architecture: who held it, in what currency, and under what conditions.</p> <p>The Bretton Woods system established in 1944 created the institutional infrastructure for post-war sovereign lending — the International Monetary Fund (IMF) and the World Bank — with mandates ostensibly oriented toward stability and development. The dollar’s role as global reserve currency, anchored until 1971 to gold, meant that international borrowing almost universally required dollar-denominated repayment. This was not a neutral technical arrangement. It meant that debtor nations needed to generate dollars — not local welfare, not ecological health, not social stability — to service their obligations.</p> <p>For industrialized nations with diversified export economies, this constraint was manageable. For the newly independent states of Africa, Asia, and Latin America emerging from colonialism in the 1950s and 1960s, it was structurally crippling. These nations inherited economies designed for extraction — mines, plantations, and resource concessions oriented toward supplying colonial metropoles — rather than domestic development. When they borrowed to build infrastructure, healthcare systems, and institutions, they borrowed in dollars. When commodity prices fell, their capacity to generate those dollars fell with them. The debt remained.</p> <p>The 1970s oil price shocks compounded the dynamic. Petrodollars recycled through private international banks flooded emerging market borrowers with cheap credit. By 1982, the combination of rising US interest rates, falling commodity prices, and ballooning debt service costs triggered what became known as the developing-world debt crisis. Mexico’s announcement in August 1982 that it could not service its external debt initiated a cascade: within two years, over forty nations were in acute debt distress.</p> <p>The institutional response was structural adjustment. The IMF and World Bank offered conditional lending — debt rescheduling in exchange for economic reforms designed to restore market confidence and generate export earnings. The conditions were consistent: reduce public expenditure, devalue the currency, liberalize trade, privatize state enterprises, prioritize export production. In country after country, the result was the same: social spending collapsed, domestic industries were outcompeted by cheap imports, and export extraction accelerated. The debts were restructured, not resolved. The 1980s became a “lost decade” for development across Latin America and sub-Saharan Africa. GDP per capita in many heavily indebted nations ended the decade below where it had started.</p> <h3><a id="ch1-2"></a>1.2 The compounding mathematics of dollar-denominated debt</h3> <p>The structural problem with dollar-denominated sovereign debt is not primarily political — it is mathematical.</p> <p>When a nation borrows in a foreign currency, it takes on an obligation that exists entirely outside its domestic monetary system. A government can, in principle, inflate away domestic currency debt by expanding the money supply. It cannot inflate away dollar-denominated debt. That debt can only be serviced by acquiring dollars — which means generating export revenue, attracting foreign investment, or borrowing more dollars to pay existing ones.</p> <p>Generating export revenue at scale, in most lower-income economies, means extracting and selling natural resources: oil, minerals, timber, agricultural commodities. The more urgent the debt service obligation, the faster extraction must proceed. There is no equilibrium in this system where the pace of extraction voluntarily slows. Slower extraction means slower dollar generation means default — with all its attendant consequences: credit rating downgrades, loss of market access, capital flight, currency crisis.</p> <p>The interest compounding dynamics make this worse over time, not better. A loan carrying a 5 percent annual interest rate doubles in approximately fourteen years. If the debtor economy is growing at 3 percent annually, the debt burden as a share of GDP grows by roughly 2 percent each year. To stabilize the debt ratio, the economy must grow at least as fast as the interest rate — and to reduce it, faster still. This is the growth imperative, and it is not a political preference. It is an arithmetic requirement built into the debt architecture.</p> <p>For a resource-extracting economy, GDP growth and natural capital depletion are not separate variables — they move together. Growing faster means extracting faster. The debt system does not merely tolerate ecological destruction as a side effect; it requires it as a precondition of fiscal stability.</p> <p><strong>Table 1.1: Debt service vs. social investment in selected nations (2023)</strong></p> <table><thead><tr><th>Country</th><th>External debt service (% of government revenue)</th><th>Health expenditure (% of GDP)</th><th>Education expenditure (% of GDP)</th></tr></thead><tbody><tr><td>Zambia</td><td>41%</td><td>2.0%</td><td>1.8%</td></tr><tr><td>Sri Lanka</td><td>56%</td><td>1.6%</td><td>1.9%</td></tr><tr><td>Pakistan</td><td>47%</td><td>1.3%</td><td>1.7%</td></tr><tr><td>Ecuador</td><td>29%</td><td>8.0%</td><td>4.4%</td></tr><tr><td>Nigeria</td><td>62%</td><td>0.8%</td><td>0.5%</td></tr></tbody></table> <p><em>Sources: World Bank, IMF Article IV consultations, 2023. Note: Figures are approximate and subject to revision as debt restructuring proceeds in several cases.</em></p> <p>The figures in Table 1.1 are not exceptional cases. They represent a structural pattern: nations directing the largest shares of government revenue to external creditors while underfunding the human development that would, in principle, generate the productivity growth needed to escape debt dependence. The trap is self-reinforcing.</p> <h3><a id="ch1-3"></a>1.3 Extraction as structural violence</h3> <p>There is a conventional way to discuss resource extraction in the context of development economics — as a necessary phase, a comparative advantage, a pathway to capital accumulation that can later be redirected toward diversification. This framing is not without historical examples: South Korea, Taiwan, and more recently Botswana have navigated commodity dependence toward more diversified economies. But these are exceptions made possible by specific institutional conditions, geopolitical timing, and, in some cases, resource scarcity that drove investment in human capital precisely because natural capital was limited.</p> <p>For most heavily indebted resource-exporting nations, extraction-led growth has not produced diversification. It has produced resource dependence, institutional capture by extractive industries, and ecological deterioration. The mechanism is not mysterious. When debt servicing requires continuous export revenue, and export revenue derives primarily from natural resource extraction, the political economy of the state becomes aligned with sustaining extraction above all else. Environmental regulations that slow extraction threaten debt serviceability. Land rights that protect communities from displacement threaten mine and plantation expansion. Diversification that redirects investment from export sectors reduces dollar generation.</p> <p>The debt system does not merely correlate with these outcomes. It creates the incentive structure that produces them.</p> <p>To call this structural violence — using Johan Galtung’s term for harm embedded in institutions rather than enacted by identifiable perpetrators — is analytically precise, not rhetorical. No individual creditor makes a decision to degrade an ecosystem. No single IMF program is designed to destroy a healthcare system. The harm emerges from the architecture, which is why addressing it requires architectural change rather than better intentions.</p> <h3><a id="ch1-4"></a>1.4 The false accounting: what debt calculations omit</h3> <p>Every sovereign debt sustainability analysis rests on an assumption so pervasive it is rarely stated: that natural capital is free.</p> <p>When the IMF calculates a country’s debt-to-GDP ratio and projects whether debt is “sustainable,” GDP is the denominator. GDP counts the value of extracted resources when they are sold, but does not count the depletion of the underlying stock. A nation that clears a forest and sells the timber records a positive contribution to GDP. The loss of the carbon sequestration, watershed protection, biodiversity, and future timber value represented by that forest does not appear anywhere in the sustainability calculation. The debt is deemed serviceable because the income covers the repayment — even if generating that income has permanently reduced the nation’s productive capacity.</p> <p>This is not an obscure accounting quirk. It is a systematic distortion that makes extractive debt strategies appear sustainable when they are not. A nation running down its natural capital to service debt is not servicing debt sustainably — it is consuming its own future productive capacity, making each subsequent year of debt service more costly in real terms.</p> <p>The Inclusive Wealth framework developed by the UN Environment Programme attempts to address this by measuring total capital — produced capital (infrastructure, machinery), human capital (health, education), and natural capital (ecosystems, minerals, fossil fuels) — as the true measure of a nation’s wealth. When natural capital depletion is included, the “development” produced by extraction-led debt service often represents net impoverishment, not wealth accumulation. Nations that appear to be developing on GDP measures are frequently destroying wealth faster than they are creating it.</p> <p>The Sovereign Debt Transformation Protocol builds this accounting correction into the debt instrument itself. By making regenerative output the measure of debt service rather than currency-denominated GDP growth, it makes the full cost of extractive strategies visible — and creates financial incentives for the alternative.</p> <hr> <h2><a id="chapter-2"></a>Chapter 2: Why growth cannot solve the problem it created</h2> <h3><a id="ch2-1"></a>2.1 The arithmetic impossibility</h3> <p>The standard prescription for debt-distressed economies is growth. Grow the economy fast enough and debt becomes manageable as a share of GDP. Generate sufficient export revenue and debt service becomes affordable. This is the logic behind every structural adjustment program, every IMF conditionality framework, every creditor insistence that the path to debt sustainability runs through economic expansion.</p> <p>The arithmetic is straightforward to state but rarely stated plainly: for this to work, GDP growth must persistently exceed the real interest rate on outstanding debt. For many lower-income nations, real interest rates on external debt — particularly private market debt acquired in periods of cheap global capital — run between 6 and 12 percent annually. Sustained GDP growth above these rates is rare anywhere; it is essentially absent in economies whose growth model depends on extracting depleting natural resources while climate change progressively disrupts agriculture, fisheries, water availability, and infrastructure.</p> <p>Consider the compounding dynamic from both directions simultaneously. The debt stock grows at the interest rate. The natural capital base — the primary source of export revenue for resource-dependent economies — depletes at the rate of extraction and degrades at the rate of climate impact. The GDP growth rate must exceed the debt growth rate while the productive base that generates GDP is shrinking. This is not a policy failure. It is an arithmetic impossibility over any sufficiently long time horizon.</p> <p>The clean version of the counterargument is that growth need not come from natural resource extraction indefinitely — that accumulation of human capital and industrial capacity eventually drives the transition. This is historically accurate for a small number of countries under specific conditions. It is not a general law, and it is not occurring in the nations most severely trapped by extractive debt dynamics. The preconditions for industrial diversification — institutional quality, infrastructure, educated workforce, stable macroeconomic environment — are precisely what get destroyed when debt distress forces austerity, outward resource extraction, and political capture by extractive industries.</p> <h3><a id="ch2-2"></a>2.2 The climate compounding</h3> <p>A factor not present in previous debt crisis analyses is now inescapable: climate change is systematically undermining the productive capacity of the most heavily indebted nations while simultaneously generating new debt through disaster response.</p> <p>The correlation is not coincidental. The nations most exposed to climate impacts — low-lying island states, Sahel-adjacent economies, South and Southeast Asian deltas — are disproportionately represented among heavily indebted lower-income countries. This is partly historical (colonial extraction concentrated in tropical regions, which are also most climate-exposed) and partly physical (tropical agriculture is more sensitive to temperature variation than temperate agriculture).</p> <p>The economic mechanism is direct. When cyclones, floods, droughts, or heat events destroy agricultural output, infrastructure, or coastal assets, GDP falls. When GDP falls, the debt-to-GDP ratio rises and market access worsens. The affected government borrows to rebuild — typically at worsened terms, given the increased risk perception — adding to the debt stock. The next climate event, worsened by the accumulated carbon emissions of industrialized nations, destroys the rebuilt infrastructure and the cycle repeats.</p> <p>Barbados, under Prime Minister Mia Mottley’s “Bridgetown Initiative,” has been among the most articulate voices for recognizing this structural injustice in international forums. The nations least responsible for cumulative greenhouse gas emissions bear the heaviest debt burden from managing the consequences. Climate adaptation spending competes directly with debt service for the same constrained government revenue. There is no path to adequate climate adaptation that runs through the existing debt architecture.</p> <p>The Sovereign Debt Transformation Protocol addresses this directly. By converting debt service from currency extraction into ecological restoration and care infrastructure development, it transforms climate adaptation spending from a cost that worsens debt sustainability into a means of servicing debt. The debtor nation that invests in mangrove restoration, watershed protection, and community health resilience is simultaneously improving its climate resilience and reducing its debt obligation. The instrument architecture aligns incentives instead of inverting them.</p> <h3><a id="ch2-3"></a>2.3 The Zambia case: a detailed example</h3> <p>Zambia’s debt trajectory illustrates the impossibility theorem in practice.</p> <p>In the early 2000s, Zambia was among the beneficiaries of the Heavily Indebted Poor Countries (HIPC) initiative — a multilateral debt relief program that cancelled approximately $3.9 billion in debt by 2005. The relief was real and provided temporary fiscal space for increased social investment. Zambia’s health and education spending increased meaningfully in the mid-2000s.</p> <p>Then copper prices spiked. Zambia borrowed heavily against its copper wealth — from bilateral creditors (primarily China), multilateral institutions, and private bondholders — to invest in infrastructure and development. Between 2012 and 2019, Zambia’s external debt rose from approximately 20 percent of GDP to over 100 percent. Copper prices fell after 2011. The debt did not.</p> <p>By 2020, Zambia had become the first African nation to default on external debt during the COVID-19 pandemic. Debt service consumed over 40 percent of government revenue. The IMF-backed restructuring process that followed stretched across three years, during which the Zambian economy contracted, social spending collapsed, and copper extraction — the only available source of foreign exchange — continued accelerating to generate the revenue that might eventually restore market access.</p> <p>The restructured debt still exists. Zambia’s copper deposits are depleting. The underlying dynamics have not changed. A generation of Zambians has experienced degraded healthcare, education, and economic opportunity to service obligations that were, from any reasonable analysis of the underlying resource base and climate trajectory, never repayable as structured.</p> <p>This is not a Zambian failure. It is a system failure. The instrument was wrong.</p> <h3><a id="ch2-4"></a>2.4 The Goodhart’s Law problem</h3> <p>There is a subtler dysfunction embedded in GDP-growth-based debt sustainability analysis: once GDP growth becomes the primary measure of debt serviceability, it becomes a target that distorts the economy in ways that undermine real productive capacity.</p> <p>Charles Goodhart, the British economist, observed that when a measure becomes a target, it ceases to be a good measure. In the context of debt-distressed economies, the perverse forms this takes are well-documented. Governments accelerate extraction to boost short-term GDP figures in advance of debt renegotiations. Informal care work, subsistence agriculture, and ecological services — which constitute a substantial share of real economic activity in many lower-income nations — are invisible in GDP calculations and therefore in debt sustainability assessments. Investments in health, education, and ecological restoration that improve long-term productive capacity but grow slowly do not generate the near-term GDP numbers that satisfy creditors.</p> <p>The result is a systematic bias toward activities that look good on creditor-facing metrics while degrading the actual productive capacity of the economy. Nations optimize for the measure rather than the underlying reality it is supposed to represent.</p> <p>The SDTP replaces GDP growth with verified regenerative output as the measure of debt serviceability. This shifts the optimization target. Governments that design policy around meeting SDTP obligations — restoring ecosystems, building care infrastructure — are simultaneously building the resilience and productive capacity that genuine long-term solvency requires. The measure and the goal are aligned rather than opposed.</p> <hr> <h2><a id="chapter-3"></a>Chapter 3: The limits of existing debt relief mechanisms</h2> <h3><a id="ch3-1"></a>3.1 A taxonomy of approaches</h3> <p>Five decades of debt crises have produced a range of institutional responses. Understanding why each falls short of addressing the structural problem clarifies what a genuine architectural solution requires.</p> <p><strong>The Paris Club and bilateral rescheduling.</strong> The Paris Club — an informal group of major creditor nations that coordinates debt rescheduling — has been the primary mechanism for managing bilateral sovereign debt distress since 1956. Its core function is rescheduling: extending repayment timelines and sometimes reducing nominal debt burdens. Paris Club agreements provide temporary relief without addressing the underlying growth imperative. They are patch operations on a failing architecture, and their creditor-coordination focus makes them increasingly inadequate as debt portfolios have diversified toward private bondholders and bilateral Chinese lending outside the Paris Club framework.</p> <p><strong>The HIPC Initiative (1996–present).</strong> The Heavily Indebted Poor Countries initiative was the first multilateral attempt at substantial debt cancellation rather than mere rescheduling. For qualifying nations that completed a multi-year IMF reform program, HIPC offered cancellation of multilateral and bilateral debt to levels deemed “sustainable.” The initiative genuinely helped — Zambia’s post-HIPC fiscal space was real, as noted above — but HIPC’s conditionality requirements embedded structural adjustment logic, qualifying nations were required to maintain IMF-approved policies before receiving full relief, and the relief proved insufficient as new borrowing cycles began. No HIPC graduate has achieved permanently sustainable debt dynamics.</p> <p><strong>The Debt Service Suspension Initiative and G20 Common Framework (2020–present).</strong> The COVID-19 pandemic prompted the G20 to launch first the DSSI (a temporary suspension of debt service payments) and then the Common Framework for Debt Treatments, a more structured approach to coordinating debt relief across G20 creditors. The Common Framework represented genuine institutional innovation in attempting to include China — now a major bilateral creditor — in coordinated debt treatment. In practice, it has been slow, opaque, and has covered very few countries. Zambia’s three-year restructuring under the Common Framework is illustrative of both the potential and the limitations.</p> <p><strong>IMF Special Drawing Rights allocations.</strong> The IMF’s 2021 allocation of $650 billion in Special Drawing Rights — reserve assets that countries can exchange for hard currency — was the largest in the institution’s history and provided meaningful liquidity to many lower-income nations. SDR allocations do not address debt stock; they address temporary liquidity constraints. They are emergency tools, not structural solutions.</p> <p><strong>Debt-for-nature swaps.</strong> The most relevant precursor to the SDTP, debt-for-nature swaps have existed since the 1980s. In their basic form, a creditor (often a government or NGO) purchases sovereign debt at a discount on secondary markets and cancels it in exchange for the debtor nation committing equivalent funds to conservation. More recent innovations — including “blue bonds” for ocean conservation and the large-scale swap negotiated by Ecuador for Galápagos conservation in 2023 — have scaled the mechanism.</p> <p>Debt-for-nature swaps demonstrate important things: that creditors will accept alternative repayment arrangements when they offer comparable economic value, that conservation commitments can be structured as binding instruments, and that there is political appetite for this kind of transaction among both debtor governments and certain classes of creditors. They have also revealed the mechanism’s limitations: scale has been modest relative to total debt burdens, verification of conservation commitments has been inconsistent, and the basic architecture — debt cancellation in exchange for conservation spending — does not address the growth imperative built into the remaining debt.</p> <h3><a id="ch3-2"></a>3.2 The common failure mode</h3> <p>Each of these mechanisms shares a fundamental limitation: they treat debt relief as a quantity problem rather than an architecture problem.</p> <p>The question they address is “how much debt should be cancelled or rescheduled?” The question they do not address is “why is this debt architecture systematically producing outcomes incompatible with human welfare and ecological survival?”</p> <p>Cancelling 30 percent of Zambia’s debt stock leaves the remaining 70 percent governed by the same architecture — denominated in dollars, requiring currency-generating export extraction, compounding at rates that will restore the original debt burden within years unless growth rates are implausibly high. The relief is real but temporary. The architecture reproduces the problem.</p> <p>An architecture-level solution requires changing what debt service means — not how much of it is owed but what is accepted as payment, what measure determines sustainability, and what governance structure verifies and adjudicates compliance. This is what the SDTP attempts.</p> <h3><a id="ch3-3"></a>3.3 The creditor incentive problem</h3> <p>One reason existing mechanisms address quantity rather than architecture is that creditors — both institutional and private — have rational incentives to preserve the current architecture even when it produces poor outcomes for debtor nations.</p> <p>Dollar-denominated debt with growth-based sustainability conditionality preserves creditor control. Creditors can continuously re-evaluate debt sustainability based on growth performance, creating leverage for policy conditionality. They can benefit from resource extraction by receiving repayment from export revenues. They can diversify their risk across many debtor nations without any single nation’s distress threatening the system. The architecture serves creditor interests even when it fails debtor ones.</p> <p>This is not a claim of bad faith. Most institutional creditors operate within fiduciary frameworks that require them to maximize return for their stakeholders — pension funds, taxpayers, shareholders. The architecture that harms Zambia is the same architecture that, from a narrow creditor perspective, functions as designed. Changing it requires either changing creditor incentives or offering creditors an alternative instrument that serves their interests better — which is precisely what the SDTP attempts through Leaves-denominated instruments backed by verifiable ecological value.</p> <h3><a id="ch3-4"></a>3.4 The missing element: regenerative accounting</h3> <p>What all existing mechanisms share — and what must change — is the treatment of ecological and social value as external to the financial calculation.</p> <p>Debt relief frameworks measure sustainability in terms of debt-to-GDP ratios, debt service-to-revenue ratios, and export coverage ratios. None of these measures includes the value of the natural capital being depleted to generate the export revenue, the future costs of the climate impacts accelerated by that extraction, or the social value of the care infrastructure that debt austerity prevents building.</p> <p>A complete accounting of sovereign debt sustainability would need to include:</p> <ul><li>The net change in natural capital stock during the repayment period</li> <li>The projected future costs of climate impacts enabled by extraction-led growth</li> <li>The human capital losses from debt-service-driven austerity in health and education</li> <li>The opportunity costs of foregone regenerative investment</li></ul> <p>When these factors are included, many debt situations that appear marginally sustainable on conventional metrics become clearly unsustainable on any reasonable long-run analysis. And many alternative debt architectures that appear costly on conventional metrics — because they slow extraction and reduce near-term GDP growth — become clearly superior.</p> <p>The Sovereign Debt Transformation Protocol is, at its core, an instrument for bringing this fuller accounting into the debt instrument itself. By making regenerative output the measure of debt service, it forces both debtor and creditor to engage with the full ledger of value creation and destruction — not just the portion visible in foreign exchange flows.</p> <hr> <h2><a id="part-ii"></a>Part II: Design — The transformation mechanism</h2> <p><em>A note on development status: The instruments and infrastructure described in this section are design proposals developed within the Global Governance Frameworks project. The Hearts and Leaves currency systems, the Love Ledger platform, and the Social Resilience Council are architectural specifications — they define how these systems should work and how they relate to each other. None are currently operational. Part IV (Implementation) addresses the development pathway required to bring them into existence.</em></p> <hr> <h2><a id="chapter-4"></a>Chapter 4: Core architecture and principles</h2> <h3><a id="ch4-1"></a>4.1 The design problem</h3> <p>Designing a workable debt transformation instrument requires solving three problems simultaneously.</p> <p>The first is the <strong>valuation problem</strong>: how do you establish an exchange rate between a dollar-denominated debt obligation and units of ecological restoration or care infrastructure development? The rate must be credible to creditors (or they won’t accept it), verifiable without excessive cost (or the administrative burden defeats the purpose), and stable enough that debtor nations can plan against it.</p> <p>The second is the <strong>verification problem</strong>: how do you confirm that claimed regenerative outputs actually occurred? Existing debt-for-nature swaps have suffered badly from this problem — conservation commitments were made but monitoring was inadequate, creating the conditions for greenwashing at scale. Any instrument that creates financial incentives for reporting regenerative outputs creates corresponding incentives for misreporting them.</p> <p>The third is the <strong>governance problem</strong>: who decides the conversion rates, adjudicates disputes, and manages the system over time? This actor must be trusted by both creditors and debtors, must have technical competence to manage complex ecological and social metrics, and must have legitimate authority that cannot be captured by either side.</p> <p>The SDTP’s design addresses all three through the integrated architecture of the GGF’s economic operating system — specifically the Hearts and Leaves currency instruments, the Love Ledger verification platform design, and the Social Resilience Council governance structure.</p> <h3><a id="ch4-2"></a>4.2 Foundational principles</h3> <p>Before describing the mechanism in detail, it is worth stating the design principles that constrain it. These are not aspirational values added after the fact — they reflect genuine constraints on what kinds of instruments can function in practice.</p> <p><strong>Mutual benefit over sacrifice.</strong> The SDTP cannot require creditors to absorb losses or debtor nations to subordinate human development to ecological goals. Both sides must be better off under the transformed arrangement than under the alternatives (continued extraction-based servicing or default). This is not a political compromise — it is a functional requirement. Instruments that require one party to lose will not be adopted voluntarily, and any non-voluntary adoption will face implementation resistance that renders it ineffective.</p> <p><strong>Verified regeneration over reported regeneration.</strong> The instrument’s integrity depends entirely on the credibility of its measurement. Claimed ecological restoration that cannot be independently verified is not a debt instrument — it is a promise with no enforcement mechanism. The verification architecture must be robust enough to support financial contracts.</p> <p><strong>Governance legitimacy through pluralism.</strong> The body overseeing conversion rates and verification cannot be dominated by creditor nations (who have systematic incentives to undervalue regenerative outputs) or debtor nations (who have systematic incentives to overvalue them). It must include scientific expertise, Indigenous governance knowledge, and representation from affected communities. Legitimacy here is not a soft concern — it is a precondition of the instrument’s enforceability.</p> <p><strong>Additionality.</strong> Debt service cannot be credited against regenerative activities that would have occurred anyway. This is standard in carbon market design and is equally essential here. If a nation’s existing forest conservation counts toward debt service, the instrument creates no new regenerative output — it simply reprices existing activity. The SDTP must require activities that are genuinely additional to baseline trajectories.</p> <p><strong>Sovereignty preservation.</strong> The instrument must not become a mechanism for creditor nations to dictate land use, governance arrangements, or development priorities in debtor nations. The specific regenerative activities that qualify for debt service must be chosen by the debtor nation within a framework of eligible categories, not mandated from outside.</p> <h3><a id="ch4-3"></a>4.3 What the instrument transforms</h3> <p>To be precise about what the SDTP transforms, it helps to describe the existing sovereign debt instrument and identify exactly what changes.</p> <p>A conventional sovereign bond specifies: a principal amount, a currency (typically US dollars, euros, or another reserve currency), an interest rate, and a repayment schedule. The debtor nation’s obligation is denominated in that currency. The nation must acquire that currency — through export earnings, foreign investment, or further borrowing — to meet each payment. Failure to meet a payment constitutes default, triggering penalties, credit rating downgrades, and loss of market access.</p> <p>The SDTP transformation operates on an existing debt instrument in three steps:</p> <ol><li><p><strong>Audit and baseline establishment.</strong> The debt obligation is mapped: total principal, remaining payments, currency denomination, creditor identity. Simultaneously, ecological and care infrastructure baselines are established for the debtor nation — current forest cover, biodiversity indices, ecosystem services values, healthcare access rates, early childhood provision rates, and related metrics. These baselines are the reference point against which future regenerative outputs are measured.</p></li> <li><p><strong>Redenomination.</strong> A portion of the remaining debt obligation is converted from currency denomination to regenerative denomination — expressed in terms of verified Leaves (ecological restoration units) and Hearts (care infrastructure development units) required to extinguish the obligation. The conversion rate between currency-denominated debt and regenerative units is established by the Social Resilience Council using a methodology described in Chapter 6.</p></li> <li><p><strong>Performance structure.</strong> The redenominated debt operates as a performance instrument: the debtor nation’s obligation is extinguished proportionally as it generates verified regenerative outputs. Meeting annual targets reduces the outstanding obligation. Exceeding targets accelerates reduction. Falling short does not trigger immediate default (as currency-denominated shortfalls would) but activates a defined remediation process with graduated consequences.</p></li></ol> <p>This structure is meaningfully different from a debt-for-nature swap. In a swap, a specific quantum of debt is cancelled in exchange for a commitment. In the SDTP, the debt obligation itself is transformed into a continuing regenerative performance requirement — one that, unlike a fixed commitment, creates sustained incentives for regenerative investment across the full repayment period.</p> <hr> <h2><a id="chapter-5"></a>Chapter 5: Hearts and Leaves as debt-servicing instruments</h2> <h3><a id="ch5-1"></a>5.1 Two currencies for two dimensions of regeneration</h3> <p>The GGF’s economic architecture proposes two complementary non-fiat currencies designed to make visible and reward forms of value that conventional financial systems ignore. Both are relevant to debt transformation, and understanding their distinct logics is necessary to understand why both are needed.</p> <p><strong>Leaves</strong> are ecological restoration credits. Each Leaf unit represents a verified quantum of ecosystem service generated or restored — measured across dimensions including carbon sequestration, biodiversity recovery, watershed protection, and soil health. Leaves are generated through documented restoration and conservation activities: reforestation, wetland recovery, marine protection, regenerative agriculture transitions. They are not generated by simply maintaining existing ecosystems (that is baseline, not additionality) but by demonstrable improvement against measured starting conditions.</p> <p><strong>Hearts</strong> are care infrastructure credits. Each Heart unit represents a verified quantum of care capacity built or sustained — measured in terms of healthcare access expansion, early childhood development provision, elder care capacity, disability support, and related services that reduce structural vulnerability in populations. Hearts are generated through investment in care infrastructure: clinics, community health workers, maternal health programs, early childhood centers.</p> <p>Both currencies are proposed as components of a broader economic system in which individuals and communities also earn Hearts and Leaves for local contributions. The SDTP application differs in scale and in the nature of the generating activity — sovereign-level ecological programs and national care infrastructure investment rather than individual or community contributions. But the underlying measurement logic is shared.</p> <p>A tension worth naming explicitly: the GGF’s Leaves currency is designed to reward ecological stewardship as a form of value recognition, not as a financial commodity. The SDTP’s requirement that Leaves function as tradable debt-servicing instruments — and ultimately circulate on secondary markets — introduces financialization pressure that sits in tension with this original design intent. The concern is not hypothetical: carbon credits began as ecological incentives and evolved into instruments widely used for offsetting rather than reducing emissions, weakening the ecological purpose in favour of market liquidity. The SDTP design attempts to manage this tension through strict additionality requirements and governance oversight, but does not resolve it. It is an open design question whether a Leaves instrument can maintain ecological integrity while also being liquid enough to attract creditor participation at scale. Phase 1 pilots should treat this tension as an explicit test question rather than an assumed solved problem.</p> <h3><a id="ch5-2"></a>5.2 Why two instruments rather than one</h3> <p>The separation matters. Combining ecological and social regeneration into a single index would create problematic substitution dynamics: a nation could meet its obligation entirely through forest planting while its healthcare system collapsed, or entirely through hospital construction while deforestation accelerated. The two-currency structure prevents this by requiring minimum performance across both dimensions.</p> <p>It also reflects a genuine insight about regeneration: healthy ecosystems and healthy human communities are not independent goals that happen to be pursued simultaneously. They are mutually reinforcing. Watershed protection improves food security and reduces waterborne disease. Community health infrastructure reduces pressure on forest resources by enabling families to meet subsistence needs through dignified work rather than extraction. The SDTP’s obligation structure, requiring performance on both dimensions, embeds this interdependence in the instrument design.</p> <h3><a id="ch5-3"></a>5.3 Leaves in more detail: what qualifies and how measurement works</h3> <p>For Leaves to function as a debt-servicing instrument, their generation must be verifiable to a standard that financial contracts can rely on. This requires specifying what activities qualify, what measurement methodology applies, and what the verification process looks like.</p> <p><strong>Qualifying activities</strong> fall into five broad categories:</p> <p><em>Forest protection and restoration.</em> Primary forest protection (where additionality can be demonstrated — typically in areas facing documented deforestation pressure) and active reforestation of degraded lands. Measurement draws on satellite remote sensing, ground-truth sampling, and carbon accounting methodologies established in the Verified Carbon Standard and similar frameworks.</p> <p><em>Wetland and coastal ecosystem recovery.</em> Mangrove restoration, seagrass bed recovery, coral reef protection, and inland wetland rehabilitation. These ecosystems are among the most carbon-dense and biodiversity-rich on Earth while also providing critical coastal protection services. Measurement combines remote sensing with biological survey data.</p> <p><em>Freshwater ecosystem health.</em> Watershed protection, river restoration, and aquifer recharge maintenance. Measured through water quality indicators, flow regime data, and associated biodiversity metrics.</p> <p><em>Soil health and regenerative agriculture.</em> Transition from extractive to regenerative agricultural practices, measured through soil carbon content, biological activity indices, and erosion rates.</p> <p><em>Marine protection.</em> Designated marine protected areas with documented enforcement and biological recovery indicators.</p> <p>These categories are not exhaustive, and the SDTP design anticipates that the SRC will expand them as measurement science develops. What matters is the principle: qualifying activities must have measurable ecological outcomes against established baselines, using methodologies with scientific consensus behind them.</p> <p><strong>Measurement methodology</strong> builds on existing frameworks — particularly the carbon accounting infrastructure developed over the past two decades — rather than inventing new systems. This is deliberate. A novel measurement framework developed specifically for the SDTP would face credibility challenges that leveraging established science avoids. Where existing frameworks have gaps or limitations (biodiversity measurement is significantly less mature than carbon accounting), the SDTP design acknowledges these and proposes that Leaves generation in those areas carry wider uncertainty ranges with conservative crediting.</p> <h3><a id="ch5-4"></a>5.4 Hearts in more detail: what qualifies and how measurement works</h3> <p>Care infrastructure measurement is substantially less technically mature than ecological measurement, and the gap is wider than the framing of this paper might suggest. Carbon markets have spent thirty years developing accounting methodologies and <em>still</em> face recurring integrity crises — greenwashing, phantom credits, reclassified baselines. Healthcare access, early childhood provision, and mental health services are harder to verify remotely, more susceptible to gaming through administrative reclassification, and more contested cross-culturally in their very definition. A government could “expand coverage” on paper by relabelling existing services without deploying a single additional health worker. The three-tier verification structure provides meaningful protection against this, but Hearts verification is the weakest technical link in the SDTP and should be treated as such.</p> <p>The proposed approach focuses on structural capacity rather than outcomes — documenting expansion in care service capacity relative to baseline rather than attempting to measure health or wellbeing directly. This is a deliberate methodological conservatism: outcomes are subject to confounders far beyond any government’s control, while structural capacity is at least in principle verifiable.</p> <p><strong>Qualifying activities</strong> include:</p> <p><em>Primary healthcare access expansion.</em> Additional population covered by accessible primary healthcare, measured through facility density, catchment population data, and service utilization rates.</p> <p><em>Community health worker programs.</em> Trained and employed community health workers providing preventive and primary care, with documented coverage and activity rates. This is the most verifiable Hearts-generating activity in Phase 1 — individual workers can be enumerated, training records checked, and coverage areas mapped.</p> <p><em>Early childhood development.</em> Enrollment capacity in quality early childhood programs, measured against age-cohort population and established quality standards.</p> <p><em>Elder and disability care infrastructure.</em> Formal and community-based care capacity for elderly and disabled populations, with documented quality standards.</p> <p><em>Mental health and psychosocial support.</em> Community-accessible mental health services, an area of particular importance in contexts of conflict and displacement — and also one of the hardest to measure consistently across cultural contexts.</p> <p><strong>A tiered approach to Hearts deployment:</strong> Given the measurement maturity gap, the SDTP implementation pathway should be explicit about what “good enough” verification looks like at each phase rather than applying a single aspirational standard uniformly. Phase 1 pilots should restrict Hearts generation to the most verifiable activities — community health worker programs and facility-based primary care expansion — where enumerable inputs and basic administrative records provide reasonable verification ground. More diffuse activities (mental health services, community-based elder care) should be deferred to Phase 2, when the Hearts measurement methodology has been refined against real-program data. Conversion rates for Hearts in Phase 1 should carry explicit uncertainty discounts reflecting this immaturity, with the expectation that rates are recalibrated as methodology improves.</p> <p>This is operationally demanding and represents one of the areas where the SDTP design most needs expert development — specifically, a dedicated Hearts measurement methodology paper (identified as a priority in the research agenda) before Phase 1 pilots deploy Hearts-denominated obligations.</p> <h3><a id="ch5-5"></a>5.5 The Love Ledger as verification infrastructure</h3> <p>The proposed Love Ledger platform is, in its GGF context, a transparent community-led system for recording care contributions and ecological stewardship activities. Its design emphasizes public accessibility, tamper-resistance, and separation between monetized recognition (Hearts) and non-monetized acknowledgment.</p> <p>For SDTP purposes, the relevant Love Ledger functions are the recording and verification layers that document regenerative activities and support the generation of Hearts and Leaves. The platform is designed to provide an auditable record — accessible to the SRC, to creditors, and to the public — of what activities have occurred, when, where, and with what independently verified outcomes.</p> <p>The key design feature that matters for the SDTP is <strong>architectural separation between activity recording and verification</strong>. The same institution that records an activity cannot be the one that verifies it. This separation is standard in financial auditing and is essential here to prevent the gaming of a system where financial incentives create pressure to over-report.</p> <p>To be clear: the Love Ledger does not currently exist as built software. What exists is a detailed architectural specification describing how the platform should function, what data structures it requires, and how it interfaces with the SRC governance processes. Developing this specification into functioning infrastructure is a significant undertaking — one that Chapter 12 addresses as a component of the pilot program design.</p> <hr> <h2><a id="chapter-6"></a>Chapter 6: Governance, verification, and the Social Resilience Council</h2> <h3><a id="ch6-1"></a>6.1 The governance problem in sovereign debt</h3> <p>Existing sovereign debt restructuring occurs within an institutional framework that is transparently creditor-dominated. The Paris Club is a creditor organization. IMF conditionality is designed and enforced by an institution whose voting structure gives dominant weight to the largest creditor nations. Private bondholder committees negotiate terms in their own interest. Debtor nations participate in these processes from a structurally weak position — a position made weaker by the fact that default is typically more costly to them than to their creditors.</p> <p>The SDTP requires a governance structure that breaks this asymmetry. If conversion rates between debt obligations and regenerative units are set by a creditor-dominated body, they will be set to systematically undervalue regenerative outputs, requiring more restoration and care investment per dollar of debt reduction than genuine equivalence would require. This is not speculation — it is the predictable consequence of asymmetric power in standard negotiating situations.</p> <p>The Social Resilience Council (SRC), as proposed in the GGF’s meta-governance architecture, is designed to avoid this through compositional pluralism: representation from debtor and creditor nations, scientific expertise in ecology and social systems, Indigenous governance knowledge holders, and civil society observers. No single constituency holds a majority. Decisions on conversion rates require qualified consensus rather than simple majority vote.</p> <p>The SRC does not currently exist. Like the Love Ledger, it is a governance design specification. The SDTP’s viability depends substantially on the SRC being established with the composition and mandate its design specifies — a body captured by either creditor interests or debtor governments would produce systematically distorted conversion rates that would either make the instrument unattractive to creditors or impose unjust burdens on debtor nations.</p> <h3><a id="ch6-2"></a>6.2 Setting conversion rates</h3> <p>The conversion rate question — how many Leaves or Hearts extinguish one dollar of debt — is the most consequential technical decision in the SDTP design. Get it wrong and the instrument either offers no relief (rates too unfavorable to debtors) or becomes a mechanism for debt cancellation through cheap ecological gestures (rates too favorable).</p> <p>The proposed methodology has three components:</p> <p><strong>Ecosystem service valuation baselines.</strong> Established economic methodologies for valuing ecosystem services — particularly the work associated with the TEEB (The Economics of Ecosystems and Biodiversity) initiative and subsequent refinements — provide reference points for what verified ecological restoration is worth in economic terms. These valuations are imperfect and contested, but they provide a starting point that is scientifically grounded and creditor-legible.</p> <p><strong>Additionality-adjusted crediting.</strong> Not all verified regeneration qualifies at face value. The SRC applies additionality factors based on the assessed probability that the activity would have occurred without the SDTP incentive. High-additionality activities (restoration in areas facing documented deforestation pressure, care infrastructure expansion in underserved areas) receive full credit. Lower-additionality activities receive partial credit. This adjustment is standard in carbon market design and essential for instrument integrity.</p> <p><strong>Periodic rate review.</strong> Conversion rates are not fixed permanently. The SRC reviews rates at defined intervals (proposed: every three years) using updated ecosystem service valuations, evolving understanding of additionality factors, and observed outcomes from operating SDTP arrangements. This allows rates to reflect improving measurement science without subjecting debtor nations to unpredictable mid-period changes.</p> <p>The rate-setting process must be transparent and its methodology publicly documented. Black-box conversion rates decided by opaque deliberation would be both scientifically indefensible and politically unsustainable.</p> <h3><a id="ch6-3"></a>6.3 Verification independence</h3> <p>The verification of regenerative outputs — confirming that claimed Leaves and Hearts were actually generated — must be structurally independent of both the debtor nation and the creditors. This is not an unusual requirement in financial instruments: independent audit is standard in corporate accounting, and third-party verification is established in carbon markets.</p> <p>The SDTP proposes a three-tier verification structure:</p> <p><strong>Tier 1: National monitoring systems.</strong> Debtor nations establish and operate national ecological and social monitoring systems, with data submitted to the Love Ledger platform in standardized formats.</p> <p><strong>Tier 2: Independent civil society verification.</strong> Accredited civil society organizations — environmental monitoring groups, healthcare access organizations, community-based ecological monitors — conduct independent verification of Tier 1 data against on-the-ground conditions. Civil society verifiers must have legal protection against government interference with their activities; this protection is a prerequisite for participation in the SDTP program.</p> <p><strong>Tier 3: SRC technical audit.</strong> The Social Resilience Council’s technical secretariat conducts periodic audit of both Tier 1 and Tier 2 data, using remote sensing, statistical sampling, and cross-system analysis to identify anomalies.</p> <p>Disputes between the national government and civil society verifiers, or between the national government and the SRC audit, are adjudicated through a defined process before the Digital Justice Tribunal — the enforcement mechanism within the GGF’s broader justice framework.</p> <h3><a id="ch6-4"></a>6.4 What happens when targets are missed</h3> <p>The proposed graduated response system works as follows:</p> <p><strong>Minor shortfall (less than 15 percent below annual target):</strong> Deficit carried forward to the following year without penalty.</p> <p><strong>Moderate shortfall (15–30 percent below target):</strong> Deficit carried forward with a time-limited remediation plan. The SRC works with the debtor government to identify whether shortfall reflects implementation failure (requiring capacity support) or measurement discrepancy (requiring verification review).</p> <p><strong>Significant shortfall (more than 30 percent below target, or two consecutive years of moderate shortfall):</strong> The SRC convenes a formal review. If shortfall reflects capacity constraints or force majeure (climate events, conflict, health crises), the program is restructured. If it reflects non-compliance or systematic misreporting, the redenominated debt reverts to conventional currency denomination for the affected portion — the debtor nation loses the SDTP benefit for that quantum without triggering broader default on the remaining portion.</p> <hr> <h2><a id="chapter-7"></a>Chapter 7: Legal framework and creditor integration</h2> <h3><a id="ch7-1"></a>7.1 The legal novelty problem</h3> <p>No legal precedent exists for a sovereign debt instrument denominated in ecological restoration units. This is a significant obstacle. Sovereign debt is governed by a complex web of domestic laws (the debtor nation’s legal system), creditor jurisdiction laws (typically English or New York law for private bonds), bilateral investment treaties, and multilateral frameworks. Introducing a new form of obligation denomination requires either adapting existing legal categories or developing new ones — both of which take time and require legal expertise that is largely absent from the current literature.</p> <p>The SDTP design does not attempt to resolve all of these questions — that work requires collaboration with international debt law specialists that has not yet occurred. What it does is identify the key legal questions and propose preliminary approaches.</p> <p><strong>Treaty authority.</strong> The constitutional foundation for the SDTP is the Treaty for Our Only Home’s Pillar 4 (Debt Justice) and Pillar 3 (Crisis Response). For nations that have ratified the Treaty, this provides a clear legal basis. For non-Treaty nations participating as creditors or debtors, the legal relationship requires separate bilateral or multilateral agreement.</p> <p><strong>Instrument categorization.</strong> For purposes of existing financial regulation, Leaves-denominated debt obligations are most analogous to commodity-linked bonds — instruments whose repayment terms are linked to the price or delivery of a commodity. The analogy is imperfect but provides a workable starting point for legal structuring.</p> <p><strong>Creditor consent.</strong> Transforming an existing debt obligation requires creditor consent. For bilateral debt (government-to-government), this is achievable through negotiation. For private bondholder debt, it requires either individual bondholder consent or collective action clauses — mechanisms that have been increasingly incorporated into sovereign bond contracts since the 2003 Mexico CAC precedent.</p> <h3><a id="ch7-2"></a>7.2 Designing for creditor participation</h3> <p>The case for creditor participation rests on several arguments that are genuinely compelling from a financial perspective:</p> <p><strong>Default risk reduction.</strong> The nations most burdened by extractive debt are also those at highest risk of default. An instrument that reduces the probability of default by reducing the extractive burden on debtor nations preserves creditor value even if the instrument itself carries novel risks.</p> <p><strong>Climate transition risk.</strong> The climate assets underlying extractive debt strategies — oil, gas, coal, deforestation-linked agriculture — face a long-run transition risk increasingly priced into financial markets. SDTP instruments convert this exposure from a climate-stranded extractive economy to a regenerative economy, which is a better long-run risk profile.</p> <p><strong>Leaves as investable assets.</strong> Verified Leaves are designed to be compatible with carbon market infrastructure and impact investment frameworks. Creditors who receive Leaves-denominated instruments could, in principle, trade these in secondary markets to impact investors, corporations managing carbon footprint obligations, or institutional investors with ESG mandates. The caveat entered in Chapter 5 applies here: whether Leaves can maintain ecological integrity while functioning as liquid financial instruments is a genuine open question.</p> <p><strong>Reputational and regulatory alignment.</strong> Multilateral and development bank creditors increasingly face regulatory and political pressure to demonstrate climate and development alignment. SDTP participation provides a credible mechanism for this alignment.</p> <p><strong>The collective action problem and how to address it.</strong></p> <p>These arguments establish that SDTP participation is in the collective interest of creditors. They do not establish that any individual creditor has a rational incentive to participate first. The free-rider logic is clean: if other creditors restructure their claims under the SDTP while one holdout maintains conventional terms, the holdout benefits from the fiscal space the others created — receiving full payment from government revenue no longer consumed by extraction-driven servicing — without bearing the transaction costs or novelty risk of participation. This is precisely the dynamic that has undermined the G20 Common Framework for Debt Treatments, where creditor coordination has proven extremely difficult in practice.</p> <p>The SDTP needs a specific mechanism to overcome this. Two approaches are worth incorporating into the design:</p> <p><em>Collective action clauses.</em> Sovereign bonds increasingly include CAC provisions requiring all holders to accept restructuring terms approved by a qualified supermajority (typically 75 percent by value). The SDTP should be structured so that when a qualifying supermajority of a nation’s creditors accept SDTP terms, remaining holdouts are bound — eliminating the free-rider option for commercial bond debt. For bilateral debt, equivalent language can be incorporated into the debt transformation agreement between governments. This is not a novel legal mechanism; it adapts an existing and increasingly standard instrument.</p> <p><em>First-mover Leaves allocation.</em> Creditors who participate in Phase 1 pilots receive preferential allocation of Leaves instruments — specifically, a larger Leaves quantity per dollar of debt transformed than later participants, reflecting the risk premium of early participation and creating a genuine financial incentive for being first. This allocation advantage declines at defined intervals as the instrument demonstrates track record. The mechanism is analogous to early-investor pricing in project finance and venture capital; it converts the disadvantage of novelty risk into a compensated premium rather than an uncompensated burden.</p> <p>The combination — CAC provisions eliminating holdout options for commercial debt, first-mover allocation creating positive incentives for early bilateral participation — directly addresses the collective action problem rather than relying on goodwill or shared interest in systemic outcomes.</p> <h3><a id="ch7-3"></a>7.3 Designing for debtor sovereignty</h3> <p>The key protections against the SDTP becoming a new form of conditionality are:</p> <p><strong>Eligible activity selection by debtors.</strong> Debtor nations choose which activities from the eligible categories they pursue to generate Leaves and Hearts. The creditor has no role in this selection.</p> <p><strong>No conditionality on other policies.</strong> Participation in the SDTP carries no conditionality on fiscal policy, trade policy, or other domestic governance matters. This must be legally enforceable, not a gentleman’s agreement.</p> <p><strong>Indigenous and community consent requirements.</strong> Activities that affect land and natural resources subject to Indigenous territorial rights require demonstrated Free, Prior and Informed Consent (FPIC) from affected communities before qualifying for Leaves generation.</p> <p><strong>Exit rights.</strong> Debtor nations retain the right to exit the SDTP for specific debt tranches with defined notice periods, reverting those tranches to conventional currency denomination.</p> <hr> <h2><a id="part-iii"></a>Part III: Viability</h2> <p><em>A note on methodology: This section presents analytical arguments for the SDTP’s macroeconomic viability. It does not present completed economic modeling. Formal macroeconomic modeling is identified as a priority for the next development phase and is beyond the current scope. Where numerical claims appear, they are order-of-magnitude estimates drawn from published sources or illustrative calculations and should not be treated as model outputs.</em></p> <hr> <h2><a id="chapter-8"></a>Chapter 8: Macroeconomic stability analysis</h2> <h3><a id="ch8-1"></a>8.1 The stability question</h3> <p>The core macroeconomic concern about any debt transformation instrument is stability: does it introduce new sources of volatility, create perverse incentives that undermine the financial system’s functioning, or generate systemic risks that outweigh the benefits? This chapter works through the main stability questions analytically, identifying where the SDTP appears robust, where genuine uncertainty remains, and where further modeling is required.</p> <h3><a id="ch8-2"></a>8.2 Exchange rate dynamics</h3> <p>Under the SDTP, a portion of debt service obligation shifts from currency generation to regenerative output generation. The currency demand from that portion disappears. For heavily indebted nations whose debt service is a dominant driver of export behavior, reducing debt-service-driven export pressure could reduce currency account surpluses. This sounds problematic but requires careful interpretation: a current account surplus driven primarily by extraction-for-debt-service is not a sign of economic strength — it reflects the diversion of natural capital into currency generation.</p> <p>The more significant exchange rate concern runs in the other direction: if Leaves-denominated obligations are seen by markets as less creditworthy than currency-denominated ones, participating nations might face broader credit deterioration. This argues for careful sequencing — SDTP transformation of a portion of debt while conventional servicing continues on the remainder — and active development of Leaves secondary markets before large-scale deployment.</p> <h3><a id="ch8-3"></a>8.3 Inflation and monetary effects</h3> <p>The SDTP does not involve money creation. It is a restructuring of existing obligations — replacing one repayment modality with another. Its direct monetary effects are therefore limited.</p> <p>If the Hearts dimension of the protocol drives substantial expansion of public care sector employment, this creates real wage and employment effects with monetary implications. Expansion of care employment — typically in locally supplied services — tends to circulate income domestically rather than leaking through import channels. The inflationary risk from care sector expansion is lower than equivalent expansion in capital-intensive imported-goods sectors. But this is an analytical argument, not a modeled result.</p> <p><strong>What modeling is needed:</strong> Country-specific computable general equilibrium (CGE) models incorporating the trade, employment, and monetary effects of SDTP transition. This is identified as a priority commission for the next development phase.</p> <h3><a id="ch8-4"></a>8.4 Creditor portfolio effects</h3> <p>For the most debt-distressed nations, the realistic alternative to SDTP is default, extended restructuring, or continued carrying of non-performing obligations. In that realistic comparison, SDTP instruments offer several genuine advantages:</p> <p><strong>Reduced default probability.</strong> By reducing the extractive burden on debtor economies, the SDTP reduces the structural conditions that generate default. An instrument that reduces the probability of a default event has substantial expected value even if the instrument itself carries novel risks.</p> <p><strong>Ecological asset backing.</strong> Verified Leaves represent claims on ecological assets with measurable economic value. Unlike conventional sovereign bonds backed only by future taxation capacity, Leaves instruments are backed by quantifiable natural capital value — a different, not necessarily worse, risk profile.</p> <p><strong>ESG regulatory tailwinds.</strong> Institutional investors face growing regulatory pressure to demonstrate environmental and social governance performance. SDTP instruments, with their verified ecological and social outputs, are structurally aligned with these requirements. Demand for genuinely verified green instruments currently exceeds supply.</p> <p><strong>Credit enhancement mechanisms.</strong> For early-stage deployment, risk can be reduced through multilateral development bank guarantees on first-loss tranches, political risk insurance, and blended finance structures — all well-established in development finance.</p> <h3><a id="ch8-5"></a>8.5 The systemic risk question</h3> <p>For the SDTP, systemic risk concerns do not appear significant at realistic deployment scales. The total sovereign debt of eligible heavily indebted nations represents a small fraction of global bond markets. Even aggressive SDTP deployment across all eligible nations would not stress global financial plumbing.</p> <p>The more plausible systemic concern is precedent effects: if creditors anticipate that debt-distressed nations can convert obligations to ecological performance requirements, they may price all emerging market sovereign debt at higher rates. Two responses: SDTP eligibility is not automatic — it requires meeting defined criteria, completing baseline establishment, and participating in SRC governance. And if the SDTP demonstrably reduces default rates among participating nations, the actuarial basis for risk premiums improves, partially offsetting any spread widening.</p> <hr> <h2><a id="chapter-9"></a>Chapter 9: Risk management and failure modes</h2> <h3><a id="ch9-1"></a>9.1 A taxonomy of risks</h3> <p>Comprehensive risk management requires being specific about what can go wrong, how likely it is, how serious the consequences would be, and what mitigation exists.</p> <h3><a id="ch9-2"></a>9.2 Verification failure and greenwashing</h3> <p><strong>Risk:</strong> Debtor nations systematically overreport regenerative outputs. <strong>Seriousness:</strong> High. If verification fails at scale, the SDTP becomes a mechanism for debt cancellation through falsified ecological reporting. This is not hypothetical — early carbon offset markets were plagued by verification failures that set back the development of robust carbon markets by years. <strong>Mitigation:</strong> The three-tier verification structure, with civil society independence as a prerequisite and SRC remote sensing audit as the quality assurance layer. <strong>Residual risk:</strong> Moderate, particularly in early deployment.</p> <h3><a id="ch9-3"></a>9.3 Political capture and governance failure</h3> <p><strong>Risk:</strong> The SRC is captured by creditor interests or debtor governments. <strong>Seriousness:</strong> High. A captured or dysfunctional SRC produces either unjust outcomes or an uninvestable instrument. <strong>Mitigation:</strong> Compositional safeguards (no single constituency controls a majority), transparent methodology, formal appeals processes, and staged introduction that allows the SRC to demonstrate competence at small scale. <strong>Residual risk:</strong> Moderate. Governance design can reduce capture risk but cannot eliminate it.</p> <h3><a id="ch9-4"></a>9.4 Currency and macroeconomic shocks</h3> <p><strong>Risk:</strong> External shocks reduce debtor nations’ capacity to invest in regenerative activities even when formally committed. <strong>Seriousness:</strong> Medium. The graduated response system and force majeure provisions address acute crisis situations. The deeper concern is prolonged economic stress making regenerative investment chronically unaffordable. <strong>Mitigation:</strong> Automatic payment pause mechanism during formally declared national emergencies, drawing on precedents in recent sovereign bond contracts (Jamaica, Grenada, Barbados). <strong>Residual risk:</strong> Moderate.</p> <h3><a id="ch9-5"></a>9.5 Ecological measurement science limitations</h3> <p><strong>Risk:</strong> Measurement standards considered rigorous today may be revised as science develops. <strong>Seriousness:</strong> Medium. <strong>Mitigation:</strong> Grandfathering provisions that protect existing SDTP contracts against retrospective metric revisions, conservative crediting with uncertainty discounts, and periodic rate reviews that incorporate measurement improvements prospectively. <strong>Residual risk:</strong> Low to medium.</p> <h3><a id="ch9-6"></a>9.6 Indigenous rights violations</h3> <p><strong>Risk:</strong> Qualifying regenerative activities are undertaken in territories subject to Indigenous rights without genuine FPIC. <strong>Seriousness:</strong> High — both ethically and practically. Activities lacking genuine community consent face implementation resistance, produce contested data, and expose the SDTP program to challenge through the Digital Justice Tribunal. <strong>Mitigation:</strong> FPIC requirements as eligibility criteria, Indigenous governance body representation in the SRC and Tier 2 verification, community-accessible escalation pathways. <strong>Residual risk:</strong> Medium. FPIC requirements are only as strong as their enforcement.</p> <h3><a id="ch9-7"></a>9.7 Insufficient scale</h3> <p><strong>Risk:</strong> SDTP adoption remains limited to a handful of countries, never achieving the scale needed to constitute a genuine structural alternative. <strong>Seriousness:</strong> High from the perspective of the instrument’s purpose. <strong>Mitigation:</strong> Coalition-building and pilot-demonstration strategy described in Part IV; demonstrating benefits that creditors find genuinely attractive. <strong>Residual risk:</strong> High. Scale adoption depends on political dynamics that instrument design cannot control.</p> <hr> <h2><a id="chapter-10"></a>Chapter 10: Comparison with alternatives</h2> <h3><a id="ch10-1"></a>10.1 The comparison framework</h3> <p>Evaluating the SDTP requires comparing it honestly against the alternatives: continued conventional debt servicing, unilateral default, expanded conventional debt relief, and other nature-linked instruments. Each comparison is made across the same dimensions: debt stock outcomes, ecological outcomes, human development outcomes, and financial system stability effects.</p> <h3><a id="ch10-2"></a>10.2 Versus continued conventional servicing</h3> <p>For nations where conventional servicing is genuinely sustainable, the SDTP offers no obvious advantage — the instrument addresses nations for whom conventional servicing is not a viable long-run path. For that group, continued conventional servicing preserves near-term financial certainty while producing slow ecological depletion and foregone human development investment that compounds over decades into a deeper structural crisis.</p> <p><strong>SDTP advantage:</strong> Ecological outcomes, human development outcomes, long-run debt trajectory. <strong>Conventional advantage:</strong> Near-term financial certainty, established legal framework.</p> <h3><a id="ch10-3"></a>10.3 Versus unilateral default</h3> <p>Default achieves some of the SDTP’s objectives — reducing the extractive burden, creating fiscal space — without requiring creditor consent. Its costs are well-evidenced: partial recovery rates, exclusion from capital markets during restructuring, collateral damage to the domestic financial system. Default also does not change the structural conditions that produced the debt; a nation that defaults and re-enters capital markets on conventional terms is on the same trajectory within a decade.</p> <p><strong>SDTP advantage:</strong> Market access preservation, financial system stability, mutual benefit over unilateral action. <strong>Default advantage:</strong> Speed, availability without creditor consent.</p> <h3><a id="ch10-4"></a>10.4 Versus expanded conventional debt relief</h3> <p>More HIPC, larger DSSI, more Common Framework coverage — this is what existing institutions would pursue if political will for expanded debt relief could be mobilized. Expanded conventional relief works within established frameworks and can be deployed faster. Its fundamental limitation is that it addresses debt quantity while leaving debt architecture unchanged. As the Zambia case illustrates, nations that receive substantial relief and then return to conventional borrowing on conventional terms reproduce the same dynamics within years.</p> <p>The SDTP is best understood not as a competitor to conventional relief but as its structural evolution — the endpoint toward which incremental improvements in conventional relief are slowly moving.</p> <p><strong>SDTP advantage:</strong> Structural change rather than quantity adjustment, ongoing performance incentives, scalability. <strong>Conventional relief advantage:</strong> Deployment speed, established legal framework, lower governance requirements.</p> <h3><a id="ch10-5"></a>10.5 Versus other nature-linked instruments</h3> <p>Sustainability-linked bonds, green bonds, and “debt-for-climate” arrangements all link sovereign debt to ecological outcomes in some way. The SDTP differs from all of them in one fundamental respect: it changes what debt service <em>means</em>, not just the conditions attached to conventional servicing. Sustainability-linked bonds modify the terms of a currency-denominated instrument; they do not replace currency denomination with regenerative denomination. A nation that misses a sustainability-linked bond KPI pays a higher interest rate — it does not, as the SDTP provides, have its remaining obligation recalibrated around a remediation plan.</p> <p>An instrument that says “your obligation is to generate verified regeneration” creates fundamentally different government behavior than one that says “your obligation is to pay $X billion, and if you also hit these ecological targets, you’ll pay slightly less.” The SDTP makes regeneration the primary obligation. Other instruments make it a modifier on a financial obligation.</p> <hr> <h2><a id="part-iv"></a>Part IV: Implementation</h2> <p><em>A note on sequencing: The implementation pathway described here is a conditional roadmap, not a project plan. Each phase depends on preconditions that cannot be assumed: Treaty ratification progress, SRC establishment, development of verification infrastructure, and the political conditions that make creditor participation possible. The timeline estimates are illustrative; the sequencing logic is the more durable claim.</em></p> <hr> <h2><a id="chapter-11"></a>Chapter 11: Three-phase transition pathway</h2> <h3><a id="ch11-1"></a>11.1 Why phasing matters</h3> <p>The SDTP cannot be deployed all at once. Its components are interdependent in ways that require sequential development: verification infrastructure must exist before performance obligations can be tracked, the SRC must be operational before conversion rates can be set, and creditors must have seen the instrument function before they will accept it at scale.</p> <p>Beyond the technical sequencing, there is a political economy argument for phasing. Novel financial instruments earn legitimacy through demonstrated performance, not theoretical elegance. Each phase of the SDTP is designed to generate evidence that makes the next phase more achievable.</p> <h3><a id="ch11-2"></a>11.2 Phase 1: Foundation and pilots (Years 1–3)</h3> <p><strong>Objective:</strong> Establish the minimum viable institutional and technical infrastructure, and generate initial evidence of the instrument’s functioning from carefully designed pilot programs.</p> <p><strong>Minimum viable governance for Phase 1.</strong> The full SDTP architecture depends on the Treaty for Our Only Home being ratified and the SRC being operational. But waiting for this institutional stack to exist before beginning any pilots is a sequencing trap — the Treaty ratification process is itself influenced by demonstrated proof-of-concept, creating a dependency loop. Phase 1 must therefore be designed to function with a lighter governance structure.</p> <p>The minimum required for a credible bilateral pilot is: one willing creditor government; one willing debtor government; an agreed measurement baseline established by independent researchers rather than the SRC; and an ad hoc verification body composed of accredited international civil society organizations operating under a memorandum of understanding rather than Treaty authority. This structure is legally simpler than the full SDTP — it is effectively a bilateral debt-for-nature agreement with enhanced verification and performance structure — but it tests the core mechanism and generates the evidence base that Phase 2 requires. The SRC, when established, would retrospectively validate Phase 1 conversions and integrate them into the broader framework.</p> <p>This means Phase 1 can begin before Treaty ratification, provided a bilateral creditor with development mandate flexibility (France’s Agence Française de Développement, the UK’s British International Investment, or Canada’s development lending arm are plausible candidates given their Bridgetown Initiative alignment) is willing to pilot with a single willing debtor. The institutional risk of this lighter structure is real — without SRC authority, conversion rate methodology is agreed ad hoc rather than set by a legitimate multilateral body — but this risk is preferable to indefinite delay.</p> <p>Once Treaty ratification is sufficiently advanced to establish the SRC with a functioning secretariat, Phase 1 transitions to full governance. The primary technical task then becomes building the Love Ledger verification architecture to a standard adequate for broader deployment: specifying data standards for Tier 1 national monitoring submissions, accrediting an initial cohort of Tier 2 civil society verifiers, and establishing the SRC technical secretariat’s remote sensing and audit capacity. This is estimated to require two to three years of focused effort.</p> <p>Pilot country selection criteria: significant external debt burden with documented sustainability concerns; existing ecological and social monitoring capacity that can be upgraded rather than built from scratch; strong independent civil society sector; government commitment to SDTP participation at ministerial level; and at least one creditor willing to participate.</p> <p>Phase 1 debt scope covers bilateral official development assistance debts only — lower political complexity than commercial bonds, greater flexibility in creditor negotiations. Phase 1 concludes with a public evaluation report — not an internal assessment — made available to potential Phase 2 participants, independent researchers, and civil society.</p> <h3><a id="ch11-3"></a>11.3 Phase 2: Scaled deployment and secondary market development (Years 4–7)</h3> <p><strong>Objective:</strong> Expand SDTP coverage to 20–30 countries, bring in private commercial creditors, establish functioning secondary markets for Leaves instruments, and complete full SRC governance composition.</p> <p>Phase 2 requires full SRC composition and creditor nation governments moving from observer status to full participation — meaning they accept SRC authority over conversion rates for their own sovereign lending. Phase 1’s demonstrated performance is intended to make this politically achievable.</p> <p>Secondary market development is not a technical afterthought — it is central to the instrument’s long-run viability. Creditors who cannot exit their positions in SDTP instruments face illiquidity risk they will price heavily into participation. Creating a secondary market requires sufficient volume of standardized instruments, market-maker commitment from at least one or two major impact-oriented financial institutions, and integration with existing carbon credit trading infrastructure.</p> <p>Phase 2 engagement should actively seek alignment with the Bridgetown Initiative’s political momentum, including potential formal endorsement from Bridgetown Initiative participants.</p> <h3><a id="ch11-4"></a>11.4 Phase 3: Systemic integration (Years 8–15)</h3> <p><strong>Objective:</strong> Integration of SDTP instruments into the standard toolkit of multilateral sovereign debt restructuring, recognition in major creditor-jurisdiction legal frameworks, and self-sustaining secondary market operation.</p> <p>Achieving systemic integration requires: IMF recognition of SDTP instruments in debt sustainability analysis frameworks; World Bank and regional development bank adoption of SDTP-compatible lending instruments for new loans; and Paris Club procedural recognition allowing SDTP as a standard option in renegotiations.</p> <p>Phase 3 also targets recognition of SDTP instruments in English and New York law as an established instrument type. By the end of Phase 3, the SDTP should require no special institutional support to function — the SRC sets conversion rates transparently, verification operates through the accredited civil society network, secondary markets provide liquidity, and new debt is being originated in SDTP-compatible forms.</p> <p>This fifteen-year horizon is not pessimism. The transition from the Brady Plan (1989) to the current Common Framework took approximately thirty years. The SDTP is attempting a more fundamental architectural change.</p> <hr> <h2><a id="chapter-12"></a>Chapter 12: Pilot program designs</h2> <h3><a id="ch12-1"></a>12.1 Design principles for pilots</h3> <p>Pilots serve two functions: testing whether the SDTP works in practice, and generating evidence that makes subsequent phases politically achievable. Both require transparency: explicit pre-registration of what the pilot is designed to test, defined success criteria established before deployment, and a commitment to publishing results regardless of outcome.</p> <h3><a id="ch12-2"></a>12.2 Pilot design A: Forest-carbon focus, bilateral official debt</h3> <p><strong>Context:</strong> A nation with significant primary forest cover, substantial deforestation pressure, and official bilateral debt concentrated in one or two creditor nations. <strong>Debt scope:</strong> Bilateral ODA debt representing approximately 15–25 percent of total external debt. <strong>Regenerative focus:</strong> Leaves through verified primary forest protection and targeted reforestation, using satellite remote sensing combined with ground-truth sampling — the most technically mature component of the Leaves system. <strong>Key test questions:</strong> Can the three verification tiers be brought into reasonable agreement? What administrative burden does the reporting requirement impose? Does the forest protection incentive shift government behavior, or primarily rebadge existing programs?</p> <h3><a id="ch12-3"></a>12.3 Pilot design B: Care infrastructure focus, multilateral debt</h3> <p><strong>Context:</strong> A nation with significant multilateral debt, documented gaps in primary healthcare access, and reasonable existing administrative capacity. <strong>Debt scope:</strong> A portion of World Bank or regional development bank lending — the natural institutional entry point given these institutions’ development mandates and lending flexibility. <strong>Regenerative focus:</strong> Hearts through community health worker program expansion, which has the strongest evidence base for rapid, scalable impact and relatively straightforward measurement. <strong>Key test questions:</strong> Can Hearts measurement methodology be applied consistently and at acceptable cost? Does the debt service incentive drive genuine expansion of care access, or redirect existing spending into SDTP-reportable categories?</p> <h3><a id="ch12-4"></a>12.4 Pilot design C: Combined focus, climate-vulnerable small island state</h3> <p><strong>Context:</strong> A small island developing state with acute climate-debt exposure, combined ecological and care infrastructure needs, and debt distributed across bilateral, multilateral, and commercial creditors. <strong>Rationale:</strong> Small island developing states are the most acute case for the SDTP, bearing the heaviest climate debt burden relative to size, with primary ecological assets among the most threatened globally. A successful SIDS pilot would generate the most politically compelling evidence for Phase 2 expansion, and the Bridgetown Initiative’s energy is concentrated in this constituency. <strong>Key test questions:</strong> Is the two-currency structure operationally manageable for a small government with limited administrative capacity? Can multi-creditor SDTP restructuring be legally structured using collective action clause mechanisms?</p> <hr> <h2><a id="chapter-13"></a>Chapter 13: Capacity building requirements</h2> <h3><a id="ch13-1"></a>13.1 The capacity gap</h3> <p>The SDTP makes significant demands on participating nations’ institutional capacity. Treating capacity building as a core implementation component — not an afterthought — is essential to avoid the instrument being disproportionately accessible to better-resourced nations.</p> <h3><a id="ch13-2"></a>13.2 National ecological monitoring capacity</h3> <p>Minimum requirements include: remote sensing access and analysis (tools are increasingly accessible — ESA Sentinel data is free, Google Earth Engine provides cloud processing at no cost for government use); ground-truth monitoring networks for satellite validation; and standardized data management systems for Love Ledger integration. The SRC technical secretariat should offer a structured national monitoring capacity assessment and development program, drawing on existing frameworks (UN-REDD, GBIF, WRI) rather than building from scratch.</p> <h3><a id="ch13-3"></a>13.3 Civil society verification capacity</h3> <p>The Tier 2 verification function requires organizations with technical competence, organizational independence, documented field presence, and institutional capacity for international accreditation. Critically, civil society capacity cannot be developed under government control — organizations established or funded by participating governments lack the independence the function requires. Capacity development must be channeled through independent intermediaries.</p> <p>Legal protection for civil society verifiers is a non-negotiable prerequisite. Governments that criminalize independent environmental monitoring or subject NGO staff to harassment cannot participate in the SDTP — not as a political condition but as a functional one.</p> <h3><a id="ch13-4"></a>13.4 Legal and negotiation capacity</h3> <p>Sovereign debt restructuring is a specialist field dominated by a small number of law firms operating primarily from New York and London — on behalf of creditors. Debtor nations frequently enter restructuring negotiations with inadequate legal representation, contributing to systematically creditor-favorable outcomes. The SDTP implementation program should include dedicated legal capacity support: access to specialist counsel with SDTP-specific expertise, template documentation that reduces negotiation costs, and peer learning networks connecting debtor nation legal teams.</p> <h3><a id="ch13-5"></a>13.5 Government program design capacity</h3> <p>Qualifying regenerative programs must be designed and managed by national governments — requiring capabilities that differ from conventional government functions and that decades of austerity have often hollowed out. Capacity building here is slower and more culturally specific than technical training. The implementation program should offer a structured government program design service: not prescribing what programs nations should run, but providing analytical and planning support within a non-conditionality framework.</p> <h3><a id="ch13-6"></a>13.6 A note on resourcing</h3> <p>The capacity building program requires sustained funding. The proposed source is the SRC operational budget, financed through a combination of Treaty-mandate multilateral contributions and a small administrative fee on SDTP transaction volumes. For Phase 1, capacity building costs should be treated as program development investment funded through development finance channels. Capacity building investment of tens of millions of dollars supports debt transformation arrangements worth billions — the return on investment is high.</p> <hr> <h2><a id="part-v"></a>Part V: Pathways to partnership</h2> <hr> <h2><a id="chapter-14"></a>Chapter 14: Guidance for specific stakeholder groups</h2> <h3><a id="ch14-1"></a>14.1 Why audience-specific framing matters</h3> <p>The SDTP requires different things from different actors. This chapter addresses each major stakeholder group directly — not to flatten the instrument’s complexity into talking points, but to identify the entry point most relevant to each audience.</p> <h3><a id="ch14-2"></a>14.2 For finance ministers and treasury officials in heavily indebted nations</h3> <p><strong>The core question you need answered:</strong> Is SDTP participation a genuine improvement on your current situation, or does it introduce new dependencies while providing inadequate relief?</p> <p>The honest answer: it depends on your debt profile, ecological and social baseline, and government program capacity. The instrument is not universally attractive. Nations with manageable debt trajectories have little reason to engage with the complexity. Nations whose debt trajectory is clearly unsustainable on conventional terms — where the arithmetic does not close — have the most to gain.</p> <p><strong>What participation requires:</strong> Establishing national monitoring baselines; designing and managing qualifying regenerative programs that are genuinely additional to existing trajectories; accepting civil society verification independent of government control.</p> <p><strong>What you should not accept:</strong> Conversion rates set without transparent methodology; conditionality on policies beyond the regenerative programs themselves; verification structures that allow creditors to audit domestic governance more broadly.</p> <p><strong>The political economy consideration:</strong> SDTP participation requires domestic political management. Agricultural, extractive, and development interests that benefit from the current architecture will perceive regenerative program requirements as constraints — because they are. Build coalition support before committing, and sequence early programs in areas where political economy allows.</p> <p><strong>Entry point:</strong> Request a preliminary SDTP eligibility and baseline assessment from the SRC secretariat when operational. This is a non-committal analytical step.</p> <h3><a id="ch14-3"></a>14.3 For bilateral creditor governments</h3> <p><strong>The core question you need answered:</strong> Does accepting SDTP restructuring improve or worsen expected returns, and how does it sit with development mandates?</p> <p>For bilateral ODA debt to highly stressed nations, the realistic alternatives are continued non-performance, protracted Paris Club renegotiation, or write-down. SDTP restructuring offers conversion of a marginal asset into a verified regenerative output with secondary market potential. The expected value comparison favors SDTP engagement in most acute distress scenarios.</p> <p>Bilateral development lenders almost universally have climate and development mandates that the SDTP directly serves. Participating in Phase 1 pilots is consistent with — and in many cases explicitly aligned with — stated development objectives.</p> <p><strong>First step:</strong> Engage with the SRC’s creditor liaison function to understand the administrative process and legal template structure. The instrument is designed to minimize novel legal drafting through standardized templates.</p> <h3><a id="ch14-4"></a>14.4 For multilateral development banks and the IMF</h3> <p><strong>The core question:</strong> How does the SDTP fit within your existing debt sustainability framework, and what institutional changes would participation require?</p> <p>The most consequential question for the IMF is whether Leaves-denominated obligations receive a different treatment in debt sustainability analysis than currency-denominated ones. If the IMF continues to treat them identically, the instrument provides no DSA benefit to participating nations — significantly reducing its attractiveness. The SDTP requires IMF methodological engagement. This is not unprecedented: the IMF has adapted sustainability frameworks in response to instrument innovation before.</p> <p>For World Bank and regional development banks, the opportunity is on the origination side — new loans originated in SDTP-compatible form, with defined ecological and care performance provisions built in from the start, create the stock of transformable debt that Phase 2 and Phase 3 require.</p> <h3><a id="ch14-5"></a>14.5 For private bondholders and institutional investors</h3> <p><strong>The core question:</strong> Is there a market here, and under what conditions?</p> <p>Distressed debt investors who have accumulated positions specifically to extract value through restructuring negotiations may find SDTP less favorable than conventional restructuring. The instrument is not designed to be attractive to extractive creditor strategies — it is designed to be attractive to creditors who prefer performing assets over extended workout situations.</p> <p>For institutional investors with ESG mandates, the secondary market for Leaves instruments — when developed in Phase 2 — is the relevant opportunity. Verified ecological outputs with transparent governance are exactly what ESG-mandated portfolios struggle to source in adequate supply.</p> <p><strong>The honest assessment:</strong> There is no established secondary market for Leaves instruments. The legal framework is undeveloped. The governance is untested. Phase 1 investment requires tolerance for genuine uncertainty — alongside the possibility of being formative participants in an instrument class that, if it scales, will be very large.</p> <h3><a id="ch14-6"></a>14.6 For Indigenous governance bodies and communities</h3> <p><strong>The core question:</strong> Does the SDTP protect our rights and recognize our authority, or does it create new mechanisms for outsiders to make decisions about our territories under an ecological banner?</p> <p>The concern is legitimate and has historical grounding. Conservation programs have a long record of displacing Indigenous communities from territories under the banner of nature protection. The SDTP must be evaluated against this history, not against its own stated intentions.</p> <p><strong>What the design provides:</strong> FPIC requirements as eligibility criteria; Indigenous governance body representation in the SRC and in Tier 2 verification; community-accessible escalation pathways to the Digital Justice Tribunal; prohibition on SDTP conditionality affecting Indigenous territorial governance.</p> <p><strong>What you need to assess:</strong> Whether FPIC requirements are genuinely enforced or are procedural compliance exercises; whether SRC representation gives substantive influence or is advisory only; whether the Digital Justice Tribunal is genuinely accessible to communities in terms of language, legal standing, and cost.</p> <p>These questions cannot be answered by the design specification. They depend on how the instrument operates in practice — which is an argument for Indigenous governance bodies to be involved in Phase 1 pilot design from the beginning, as co-designers rather than beneficiaries.</p> <h3><a id="ch14-7"></a>14.7 For civil society organizations and research institutions</h3> <p><strong>The core question:</strong> How do you engage with an instrument still in design — and what does credible engagement look like?</p> <p>For environmental and development NGOs, the Tier 2 verification function is the most concrete near-term opportunity. Organizations that wish to be part of the verification infrastructure should begin developing the technical capacity, institutional independence standards, and international accreditation frameworks the role requires — even before the SRC exists to formally accredit them.</p> <p>The more important near-term role is critical engagement with the instrument design. The SDTP has significant potential failure modes, and civil society organizations are the constituency most likely to detect and resist these in practice. Constructive critical engagement now, while the design is still open, is more valuable than opposition later.</p> <p>For research institutions and economists, the modeling gaps identified throughout this paper represent a research agenda that is both practically important and intellectually interesting. The GGF project invites formal research partnerships and is committed to publishing results regardless of whether they support or challenge the SDTP’s claims.</p> <hr> <h2><a id="part-vi"></a>Part VI: Conclusion and research agenda</h2> <hr> <h2><a id="chapter-15"></a>Chapter 15: What this paper has and has not established</h2> <h3><a id="ch15-1"></a>15.1 The honest summary</h3> <p>This paper has made a structural diagnosis and proposed an architectural response.</p> <p><strong>What it has established with reasonable confidence:</strong></p> <p>The existing sovereign debt architecture is structurally incompatible with ecological sustainability and equitable human development for the nations most burdened by it. This is not a claim about intentions — it is a claim about architecture. The growth imperative embedded in dollar-denominated, compound-interest debt structures requires extraction at a pace that depletes natural capital faster than it can be regenerated, while constraining the social investment that would enable genuine development. Existing debt relief mechanisms address quantity without addressing architecture, producing temporary relief that the underlying dynamics erode.</p> <p>The logical structure of a regenerative debt instrument is sound. The SDTP’s basic design addresses the right problem at the right level. Transforming what debt service means, rather than how much of it is owed, is the architectural intervention the diagnosis requires.</p> <p>The instrument is feasible in principle: it does not require creditors to absorb losses, does not require debtor nations to subordinate development to conservation, is compatible with existing legal frameworks as a starting point, and has genuine precedents in debt-for-nature swaps and sustainability-linked instruments.</p> <p><strong>What this paper has not established:</strong></p> <p>Formal macroeconomic modeling of the instrument’s effects. The claims in Part III are analytical arguments, not model outputs.</p> <p>Legal feasibility analysis by international debt law specialists. The legal framework described in Chapter 7 is preliminary.</p> <p>Verified engagement with creditor institutions, debtor governments, or Indigenous governance bodies. This paper is a proposal directed at these constituencies; it is not the outcome of a process in which they have participated.</p> <p>A functioning verification infrastructure. The Love Ledger platform and its associated verification processes are design specifications. The gap between specification and working software and institutional infrastructure is substantial and should not be understated.</p> <h3><a id="ch15-2"></a>15.2 The central claim, restated</h3> <p>The SDTP rests on one central claim: the instruments we use to govern sovereign debt determine the behaviors that debt-burdened nations adopt, and current instruments require behaviors that are incompatible with the future we need.</p> <p>This claim is not novel. The Bridgetown Initiative makes it. UNCTAD trade and development reports make it. Academic economists working on sovereign debt sustainability increasingly make it. What the SDTP adds is a specific architectural proposal grounded in the GGF’s broader regenerative economics framework — specific enough to be implemented if political conditions allow, and honest enough about its own limitations to invite the engagement that would make it better.</p> <p>The goal is not to win the argument. The goal is to ensure that when political conditions create an opening for structural change in global debt architecture — as they will, as the costs of the current architecture accumulate — there is a worked alternative available. The opening may come from a cascade of defaults among climate-vulnerable nations. It may come from the fiscal impossibility of climate adaptation under current debt loads becoming undeniable to creditor governments. It may come from the political realignment that accompanies the decline of current geopolitical arrangements.</p> <p>When it comes, something will fill it. This paper argues for what that something should be.</p> <hr> <h2><a id="chapter-16"></a>Chapter 16: Research agenda</h2> <h3><a id="ch16-1"></a>16.1 Priorities for formal modeling</h3> <p><strong>Macroeconomic transition modeling.</strong> Country-specific CGE models of SDTP transition effects for representative debtor nation types — covering exchange rate effects, employment impacts of care sector expansion, trade balance dynamics, and fiscal position trajectories. Appropriate for development economics research institutions; should be commissioned as a funded research program.</p> <p><strong>Creditor portfolio effects.</strong> Formal expected value analysis comparing SDTP instruments to realistic alternatives across different debt profile scenarios. Requires collaboration with sovereign debt specialists at multilateral institutions or investment banks with relevant portfolio data.</p> <p><strong>Game-theoretic analysis of adoption dynamics.</strong> Modeling of creditor behavior under different SDTP adoption scenarios — specifically whether the instrument creates precedent effects that materially widen spreads on conventional sovereign debt, and under what conditions coalition-building among debtor nations accelerates versus stalls.</p> <p><strong>Secondary market pricing models.</strong> Financial modeling of Leaves instrument pricing under different ecological verification accuracy assumptions, liquidity scenarios, and ESG regulatory environments.</p> <h3><a id="ch16-2"></a>16.2 Priorities for measurement methodology development</h3> <p><strong>Biodiversity metric standardization.</strong> The Leaves framework’s biodiversity dimension is currently the weakest link in the measurement chain — there is no single accepted methodology comparable to carbon accounting. Priority: identifying which biodiversity metrics are most closely correlated with ecosystem service value, and which are most verifiable with current monitoring technology.</p> <p><strong>Care economy measurement framework.</strong> A rigorous methodology for converting care infrastructure investment and service delivery into standardized Hearts units, calibrated across different country contexts. Requires collaboration between health economists, development researchers, and community health program practitioners.</p> <p><strong>Additionality assessment methodology.</strong> An analytical framework for assessing additionality in both ecological and care dimensions — drawing on carbon market methodology while adapting it to the SDTP’s broader scope.</p> <h3><a id="ch16-3"></a>16.3 Priorities for legal and institutional development</h3> <p><strong>Sovereign debt law analysis.</strong> A comprehensive legal opinion on SDTP instrument compatibility with English and New York law, identification of required legal innovations, and a regulatory recognition roadmap. Should be commissioned from a law firm with sovereign debt restructuring practice.</p> <p><strong>SRC governance design.</strong> Detailed institutional design for the Social Resilience Council — governance rules, composition requirements, decision-making procedures, conflict of interest policies, and accountability mechanisms. Benefits from comparative institutional analysis drawing on existing international governance bodies (IPCC, FSB, Basel Committee).</p> <p><strong>Digital Justice Tribunal access design.</strong> Specific design work on how the Tribunal can be genuinely accessible to affected communities — addressing language, standing, cost, and procedural barriers through participatory design processes.</p> <h3><a id="ch16-4"></a>16.4 Priorities for empirical evidence</h3> <p><strong>Debt-for-nature swap outcomes analysis.</strong> Systematic review of existing debt-for-nature swap outcomes — what ecological results were achieved, what governance structures worked, what failed. This empirical base is the SDTP’s most direct precedent.</p> <p><strong>Care infrastructure investment returns.</strong> Economic analysis of the long-run productivity and fiscal returns to care infrastructure investment in low-income nations — quantifying human capital, labor market, and fiscal multiplier effects.</p> <p><strong>Community impacts of conservation finance.</strong> Field research on how existing conservation finance programs affect communities in and around target ecosystems. Essential for designing SDTP programs that do not reproduce the displacement and exclusion that have characterized some earlier approaches.</p> <h3><a id="ch16-5"></a>16.5 An invitation</h3> <p>This research agenda is a specification of what is needed to move from design proposal to operational instrument. Different elements are appropriate for different institutions: academic economics departments, international financial institutions, specialist law firms, civil society research organizations, and communities with direct experience of the problems the SDTP addresses.</p> <p>The GGF project is committed to open-sourcing the analytical work that underpins this paper, engaging seriously with critical responses, and revising the instrument design in response to evidence. We do not hold the SDTP as a finished answer. We hold it as the best current version of a question that urgently needs to be asked: what would it take to make sovereign debt serve the future rather than foreclose it?</p> <p>We invite responses, critiques, collaborative research proposals, and direct engagement at globalgovernanceframeworks.org.</p> <hr> <h2><a id="appendices"></a>Appendix outline</h2> <p><em>(Appendices to be developed in subsequent drafting phases)</em></p> <p><strong>Appendix A:</strong> Technical specifications for Love Ledger reporting standards <strong>Appendix B:</strong> SRC governance rules — draft constitutional document <strong>Appendix C:</strong> Leaves measurement methodology — detailed technical specification <strong>Appendix D:</strong> Hearts measurement methodology — detailed technical specification <strong>Appendix E:</strong> Legal template — bilateral SDTP debt transformation agreement <strong>Appendix F:</strong> Case study — Ecuador Galápagos debt-for-nature swap (2023): lessons for SDTP design <strong>Appendix G:</strong> Case study — Zambia debt restructuring (2020–2023): what a functioning SDTP would have changed <strong>Appendix H:</strong> Glossary of key terms <strong>Appendix I:</strong> Bibliography and data sources</p>',1);function k(e){var t=o();n(872),a(e,t)}export{k as default,r as metadata};
